SELECT a.id, article_cover, article_title, ai_summary, ai_summary_status, ai_summary_time, type, is_top, a.is_delete, a.status, a.create_time, category_name, t.id AS tag_id, t.tag_name FROM ( SELECT id, article_cover, article_title, ai_summary, ai_summary_status, ai_summary_time, type, is_top, is_delete, status, create_time, category_id FROM tb_article
is_delete = #{condition.isDelete}
and article_title like concat('%',#{condition.keywords},'%')
and status = #{condition.status}
and category_id = #{condition.categoryId}
and type = #{condition.type}
and id in ( SELECT article_id FROM tb_article_tag WHERE tag_id = #{condition.tagId} )
ORDER BY is_top DESC, id DESC LIMIT #{current},#{size} ) a LEFT JOIN tb_category c ON a.category_id = c.id LEFT JOIN tb_article_tag atg ON a.id = atg.article_id LEFT JOIN tb_tag t ON t.id = atg.tag_id ORDER BY is_top DESC, a.id DESC

SELECT
count(DISTINCT a.id)
from
tb_article a
LEFT JOIN tb_article_tag tat on  a.id = tat.article_id

    is_delete = #{condition.isDelete}

        and article_title like concat('%',#{condition.keywords},'%')


        and `status` = #{condition.status}


        and category_id = #{condition.categoryId}


        and type = #{condition.type}


        and tat.tag_id = #{condition.tagId}

SELECT a.id, article_cover, article_title, a.create_time, a.category_id, category_name, t.id AS tag_id, t.tag_name FROM ( SELECT id, article_cover, article_title, create_time, category_id FROM tb_article WHERE is_delete = 0 AND status IN (1, 4)
AND article_title LIKE concat('%',#{condition.keywords},'%')
AND article_content LIKE concat('%',#{condition.keywords},'%')
AND (article_title LIKE concat('%',#{condition.keywords},'%') OR article_content LIKE concat('%',#{condition.keywords},'%'))
AND category_id = #{condition.categoryId}
AND id IN (SELECT article_id FROM tb_article_tag WHERE tag_id = #{condition.tagId})
AND create_time >= #{condition.startTime}
AND create_time <= #{condition.endTime}
ORDER BY id DESC LIMIT #{current},#{size} ) a JOIN tb_category c ON a.category_id = c.id JOIN tb_article_tag atg ON a.id = atg.article_id JOIN tb_tag t ON t.id = atg.tag_id

SELECT count(DISTINCT a.id) FROM tb_article a
LEFT JOIN tb_article_tag tat ON a.id = tat.article_id
WHERE a.is_delete = 0 AND a.status IN (1, 4)
AND a.article_title LIKE concat('%',#{condition.keywords},'%')
AND a.article_content LIKE concat('%',#{condition.keywords},'%')
AND (a.article_title LIKE concat('%',#{condition.keywords},'%') OR a.article_content LIKE concat('%',#{condition.keywords},'%'))
AND a.category_id = #{condition.categoryId}
AND tat.tag_id = #{condition.tagId}
AND a.create_time >= #{condition.startTime}
AND a.create_time <= #{condition.endTime}
